good.code:
public class AgeCheck {
    public static void main(String[] args) {
        int[] ages = {10, 40, 70};
        for (int age : ages) {
            if (age >= 18 && age <= 65) {
                System.out.println("accepted " + age);
            }
        }
    }
}

